TA_RetCode TA_MA( int startIdx,
                             int endIdx,
                             const double inReal[],
                             int optInTimePeriod,
                             TA_MAType optInMAType,
                             int *outBegIdx,
                             int *outNBElement,
                             double outReal[] )
{
   TA_RetCode retCode;
   int nbElement;
   int outIdx;
   int todayIdx;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( (int)optInMAType == ((-0x7fffffff - 1)) || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < 0 || (int)optInMAType > 15 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   if( TA_MA_Lookback(optInTimePeriod,optInMAType) > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod == 1 || optInMAType == TA_MAType_DISABLED )
   {
      nbElement = endIdx - startIdx + 1;
      *outNBElement= nbElement;
      for( todayIdx = startIdx, outIdx = 0; outIdx < nbElement; outIdx += 1, todayIdx += 1 )
      {
         outReal[outIdx] = inReal[todayIdx];
      }
      *outBegIdx= startIdx;
      return TA_SUCCESS;
   }
   switch( optInMAType )
   {
   case TA_MAType_SMA:
      retCode = TA_SMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_EMA:
      retCode = TA_EMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_WMA:
      retCode = TA_WMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_DEMA:
      retCode = TA_DEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_TEMA:
      retCode = TA_TEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_TRIMA:
      retCode = TA_TRIMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_KAMA:
      retCode = TA_KAMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_MAMA:
      retCode = TA_MAMA(startIdx,endIdx,inReal,0.5,0.05,outBegIdx,outNBElement,outReal,((void *)0));
      break;
   case TA_MAType_T3:
      retCode = TA_T3(startIdx,endIdx,inReal,optInTimePeriod,0.7,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_HMA:
      retCode = TA_HMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_ZLEMA:
      retCode = TA_ZLEMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_RMA:
      retCode = TA_RMA(startIdx,endIdx,inReal,optInTimePeriod,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_VIDYA:
      retCode = TA_VIDYA(startIdx,endIdx,inReal,optInTimePeriod,(3 * optInTimePeriod + 2) / 4,outBegIdx,outNBElement,outReal);
      break;
   case TA_MAType_ALMA:
      retCode = TA_ALMA(startIdx,endIdx,inReal,optInTimePeriod,6.0,0.85,outBegIdx,outNBElement,outReal);
      break;
   default:
      retCode = TA_BAD_PARAM;
      break;
   }
   return retCode;
}
int TA_MA_Lookback( int optInTimePeriod, TA_MAType optInMAType )
{
   int retValue;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return -1;
   if( (int)optInMAType == ((-0x7fffffff - 1)) || optInMAType == TA_MAType_DEFAULT )
      optInMAType = 0;
   else if( (int)optInMAType < 0 || (int)optInMAType > 15 )
      return -1;
   if( optInTimePeriod <= 1 || optInMAType == TA_MAType_DISABLED )
   {
      return 0;
   }
   switch( optInMAType )
   {
   case TA_MAType_SMA:
      retValue = TA_SMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_EMA:
      retValue = TA_EMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_WMA:
      retValue = TA_WMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_DEMA:
      retValue = TA_DEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_TEMA:
      retValue = TA_TEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_TRIMA:
      retValue = TA_TRIMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_KAMA:
      retValue = TA_KAMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_MAMA:
      retValue = TA_MAMA_Lookback(0.5,0.05);
      break;
   case TA_MAType_T3:
      retValue = TA_T3_Lookback(optInTimePeriod,0.7);
      break;
   case TA_MAType_HMA:
      retValue = TA_HMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_ZLEMA:
      retValue = TA_ZLEMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_RMA:
      retValue = TA_RMA_Lookback(optInTimePeriod);
      break;
   case TA_MAType_VIDYA:
      retValue = TA_VIDYA_Lookback(optInTimePeriod,(3 * optInTimePeriod + 2) / 4);
      break;
   case TA_MAType_ALMA:
      retValue = TA_ALMA_Lookback(optInTimePeriod,6.0,0.85);
      break;
   default:
      retValue = 0;
      break;
   }
   return retValue;
}
TA_RetCode TA_ALMA( int startIdx,
                               int endIdx,
                               const double inReal[],
                               int optInTimePeriod,
                               double optInSigma,
                               double optInOffset,
                               int *outBegIdx,
                               int *outNBElement,
                               double outReal[] )
{
   double sum;
   double s;
   double twoSSq;
   double d;
   double norm;
   double wj;
   double s0;
   double s1;
   double s2;
   double s3;
   int lookbackTotal;
   int outIdx;
   int i;
   int j;
   int w;
   int m;
   int b;
   double local_weights[30];
   double *weights = &local_weights[0];
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 9;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( optInSigma == (-4e+37) )
      optInSigma = 6;
   else if( !(optInSigma >= 1e-2 && optInSigma <= (3e+37)) )
      return TA_BAD_PARAM;
   if( optInOffset == (-4e+37) )
      optInOffset = 0.85;
   else if( !(optInOffset >= 0e0 && optInOffset <= 1e0) )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   lookbackTotal = optInTimePeriod - 1;
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod == 1 )
   {
      *outBegIdx= startIdx;
      *outNBElement= endIdx - startIdx + 1;
      i = startIdx;
      for( outIdx = 0; outIdx < (int)*outNBElement; outIdx += 1 )
      {
         outReal[outIdx] = inReal[i++];
      }
      return TA_SUCCESS;
   }
   if( optInTimePeriod < 1 ) return ((TA_RetCode)(TA_INTERNAL_ERROR+459));
   if( (int)optInTimePeriod > (int)(sizeof(local_weights)/sizeof(double)) )
   {
      weights = malloc(sizeof(double)*optInTimePeriod);
      if( !weights )
      {
         return TA_ALLOC_ERR;
      }
   }
   else
   {
      weights = &local_weights[0];
   }
   m = (int)floor(optInOffset * (double)lookbackTotal);
   s = (double)optInTimePeriod / optInSigma;
   twoSSq = 2.0 * s * s;
   norm = 0.0;
   for( j = 0; j < optInTimePeriod; j += 1 )
   {
      d = (double)(j - m);
      weights[j] = exp(-(d * d) / twoSSq);
      norm += weights[j];
   }
   for( j = 0; j < optInTimePeriod; j += 1 )
   {
      weights[j] = weights[j] / norm;
   }
   outIdx = 0;
   i = startIdx;
   while( i + 3 <= endIdx )
   {
      s0 = 0.0;
      s1 = 0.0;
      s2 = 0.0;
      s3 = 0.0;
      b = i - lookbackTotal;
      for( j = 0; j < optInTimePeriod; j += 1 )
      {
         wj = weights[j];
         s0 += wj * inReal[b];
         s1 += wj * inReal[b + 1];
         s2 += wj * inReal[b + 2];
         s3 += wj * inReal[b + 3];
         b += 1;
      }
      outReal[outIdx] = s0;
      outReal[outIdx + 1] = s1;
      outReal[outIdx + 2] = s2;
      outReal[outIdx + 3] = s3;
      outIdx += 4;
      i += 4;
   }
   while( i <= endIdx )
   {
      sum = 0.0;
      w = 0;
      for( j = i - lookbackTotal; j <= i; j += 1 )
      {
         sum += weights[w] * inReal[j];
         w += 1;
      }
      outReal[outIdx] = sum;
      outIdx += 1;
      i += 1;
   }
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   if( weights != &local_weights[0] ) { free(weights); weights = &local_weights[0]; }
   return TA_SUCCESS;
}
TA_RetCode TA_DEMA( int startIdx,
                               int endIdx,
                               const double inReal[],
                               int optInTimePeriod,
                               int *outBegIdx,
                               int *outNBElement,
                               double outReal[] )
{
   double prevEMA1;
   double prevEMA2;
   double tempReal;
   double optInK_1;
   double emaBeta;
   int i;
   int today;
   int outIdx;
   int lookbackEMA;
   int lookbackTotal;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 30;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   *outNBElement= 0;
   *outBegIdx= 0;
   lookbackEMA = TA_EMA_Lookback(optInTimePeriod);
   lookbackTotal = lookbackEMA * 2;
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      return TA_SUCCESS;
   }
   if( optInTimePeriod == 1 )
   {
      *outBegIdx= startIdx;
      outIdx = 0;
      today = startIdx;
      while( today <= endIdx )
      {
         outReal[outIdx++] = inReal[today++];
      }
      *outNBElement= outIdx;
      return TA_SUCCESS;
   }
   emaBeta = (double)(optInTimePeriod - 1) / (double)(optInTimePeriod + 1);
   optInK_1 = 1.0 - emaBeta;
   if( emaBeta < 0.5 )
   {
      emaBeta = 1.0 - optInK_1;
   }
   today = startIdx - lookbackTotal;
   i = optInTimePeriod;
   tempReal = 0.0;
   while( i-- > 0 )
   {
      tempReal += inReal[today++];
   }
   prevEMA1 = tempReal / optInTimePeriod;
   while( today <= startIdx - lookbackEMA )
   {
      prevEMA1 = fma(emaBeta, prevEMA1, optInK_1 * inReal[today++]);
   }
   tempReal = 0.0;
   tempReal += prevEMA1;
   i = optInTimePeriod - 1;
   while( i-- > 0 )
   {
      prevEMA1 = fma(emaBeta, prevEMA1, optInK_1 * inReal[today++]);
      tempReal += prevEMA1;
   }
   prevEMA2 = tempReal / optInTimePeriod;
   while( today <= startIdx )
   {
      prevEMA1 = fma(emaBeta, prevEMA1, optInK_1 * inReal[today++]);
      prevEMA2 = fma(emaBeta, prevEMA2, optInK_1 * prevEMA1);
   }
   outReal[0] = 2.0 * prevEMA1 - prevEMA2;
   outIdx = 1;
   while( today <= endIdx )
   {
      prevEMA1 = fma(emaBeta, prevEMA1, optInK_1 * inReal[today++]);
      prevEMA2 = fma(emaBeta, prevEMA2, optInK_1 * prevEMA1);
      outReal[outIdx++] = 2.0 * prevEMA1 - prevEMA2;
   }
   *outBegIdx= startIdx;
   *outNBElement= outIdx;
   return TA_SUCCESS;
}
