   double lowest;
   double ratio;
   double smoothed;
   double fish;
   double prevFish;
   double tempReal;
   double tempHigh;
   double tempLow;
   int outIdx;
   int lookbackTotal;
   int unstablePeriod;
   int nbInitialElementNeeded;
   int today;
   int i;
   int m;
   int blockStart;
   int blockNext;
   int nAvail;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 10;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outFisher )
      return TA_BAD_PARAM;
   if( !outTrigger )
      return TA_BAD_PARAM;
   if( outFisher == outTrigger )
      return TA_BAD_PARAM;
   nbInitialElementNeeded = TA_FISHER_Lookback(optInTimePeriod);
   if( startIdx < nbInitialElementNeeded )
   {
      startIdx = nbInitialElementNeeded;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   lookbackTotal = optInTimePeriod - 1;
   unstablePeriod = nbInitialElementNeeded - lookbackTotal;
   smoothed = 0.0;
   prevFish = 0.0;
   today = startIdx - unstablePeriod;
   blockStart = today - lookbackTotal;
   outIdx = 0;
