   return optInTimePeriod - 1 + ( 0U <= (unsigned int)100000000 ? (int)0U : 0U == (unsigned int)(100000000 +4) ? (int)((5 * (10 + 6) + 1) / 2) : (int)((5 * (19 + 6) + 1) / 2) );
