int ti_dema_start(double const *options) {
    const int period = (int)options[0];
    return (period-1) * 2;
}
int ti_dema(int size, double const *const *inputs, double const *options, double *const *outputs) {
    const double *input = inputs[0];
    const int period = (int)options[0];
    double *output = outputs[0];
    if (period < 1) return 1;
    if (size <= ti_dema_start(options)) return 0;
    const double per = 2 / ((double)period + 1);
    const double per1 = 1.0 - per;
    double ema = input[0];
    double ema2 = ema;
    int i;
    for (i = 0; i < size; ++i) {
        ema = ema * per1 + input[i] * per;
        if (i == period-1) {
            ema2 = ema;
        }
        if (i >= period-1) {
            ema2 = ema2 * per1 + ema * per;
            if (i >= (period-1) * 2) {
                *output = ema * 2 - ema2;
                ++output;
            }
        }
    }
    ((void) (0));
    return 0;
}
int ti_atr_start(double const *options) {
    return (int)options[0]-1;
}
int ti_atr(int size, double const *const *inputs, double const *options, double *const *outputs) {
    const double *high = inputs[0];
    const double *low = inputs[1];
    const double *close = inputs[2];
    const int period = (int)options[0];
    double *output = outputs[0];
    if (period < 1) return 1;
    if (size <= ti_atr_start(options)) return 0;
    const double per = 1.0 / ((double)period);
    double sum = 0;
    double truerange;
    sum += high[0] - low[0];
    int i;
    for (i = 1; i < period; ++i) {
        do{ const double l = low[i]; const double h = high[i]; const double c = close[i-1]; const double ych = fabs(h - c); const double ycl = fabs(l - c); double v = h - l; if (ych > v) v = ych; if (ycl > v) v = ycl; truerange = v;}while(0);
        sum += truerange;
    }
    double val = sum / period;
    *output++ = val;
    for (i = period; i < size; ++i) {
        do{ const double l = low[i]; const double h = high[i]; const double c = close[i-1]; const double ych = fabs(h - c); const double ycl = fabs(l - c); double v = h - l; if (ych > v) v = ych; if (ycl > v) v = ycl; truerange = v;}while(0);
        val = (truerange-val) * per + val;
        *output++ = val;
    }
    ((void) (0));
    return 0;
}
TA_RetCode TA_CHOP( int startIdx,
                               int endIdx,
                               const double inHigh[],
                               const double inLow[],
                               const double inClose[],
                               int optInTimePeriod,
                               int *outBegIdx,
                               int *outNBElement,
                               double outReal[] )
{
   int today;
   int outIdx;
   int lookbackTotal;
   int i;
   double highest;
   double lowest;
   double sumTR;
   double logPeriod;
   double tempHT;
   double tempLT;
   double prevClose;
   double trueHigh;
   double trueLow;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   *outBegIdx= 0;
   *outNBElement= 0;
   lookbackTotal = TA_CHOP_Lookback(optInTimePeriod);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      return TA_SUCCESS;
   }
   logPeriod = log10((double)optInTimePeriod);
   outIdx = 0;
   today = startIdx;
   while( today <= endIdx )
   {
      highest = inHigh[today];
      lowest = inLow[today];
      sumTR = 0.0;
      prevClose = 0.0;
      for( i = optInTimePeriod; i >= 0; i -= 1 )
      {
         if( i < optInTimePeriod )
         {
            tempHT = inHigh[today - i];
            tempLT = inLow[today - i];
            trueHigh = tempHT;
            if( prevClose > trueHigh )
            {
               trueHigh = prevClose;
            }
            trueLow = tempLT;
            if( prevClose < trueLow )
            {
               trueLow = prevClose;
            }
            sumTR += trueHigh - trueLow;
            if( tempHT > highest )
            {
               highest = tempHT;
            }
            if( tempLT < lowest )
            {
               lowest = tempLT;
            }
         }
         prevClose = inClose[today - i];
      }
      if( highest - lowest <= 0.0 || sumTR <= 0.0 )
      {
         outReal[outIdx] = 100.0;
      } else
      {
         outReal[outIdx] = 100.0 * (log10(sumTR / (highest - lowest)) / logPeriod);
      }
      outIdx += 1;
      today += 1;
   }
   *outBegIdx= startIdx;
   *outNBElement= outIdx;
   return TA_SUCCESS;
}
