int TA_KST_Lookback( int optInROC1Period, int optInROC2Period, int optInROC3Period, int optInROC4Period, int optInSMA1Period, int optInSMA2Period, int optInSMA3Period, int optInSMA4Period, int optInSignalPeriod )
{
   int legMax;
   int leg;
   if( (int)optInROC1Period == ((-0x7fffffff - 1)) )
      optInROC1Period = 10;
   else if( (int)optInROC1Period < 1 || (int)optInROC1Period > 100000 )
      return -1;
   if( (int)optInROC2Period == ((-0x7fffffff - 1)) )
      optInROC2Period = 15;
   else if( (int)optInROC2Period < 1 || (int)optInROC2Period > 100000 )
      return -1;
   if( (int)optInROC3Period == ((-0x7fffffff - 1)) )
      optInROC3Period = 20;
   else if( (int)optInROC3Period < 1 || (int)optInROC3Period > 100000 )
      return -1;
   if( (int)optInROC4Period == ((-0x7fffffff - 1)) )
      optInROC4Period = 30;
   else if( (int)optInROC4Period < 1 || (int)optInROC4Period > 100000 )
      return -1;
   if( (int)optInSMA1Period == ((-0x7fffffff - 1)) )
      optInSMA1Period = 10;
   else if( (int)optInSMA1Period < 1 || (int)optInSMA1Period > 100000 )
      return -1;
   if( (int)optInSMA2Period == ((-0x7fffffff - 1)) )
      optInSMA2Period = 10;
   else if( (int)optInSMA2Period < 1 || (int)optInSMA2Period > 100000 )
      return -1;
   if( (int)optInSMA3Period == ((-0x7fffffff - 1)) )
      optInSMA3Period = 10;
   else if( (int)optInSMA3Period < 1 || (int)optInSMA3Period > 100000 )
      return -1;
   if( (int)optInSMA4Period == ((-0x7fffffff - 1)) )
      optInSMA4Period = 15;
   else if( (int)optInSMA4Period < 1 || (int)optInSMA4Period > 100000 )
      return -1;
   if( (int)optInSignalPeriod == ((-0x7fffffff - 1)) )
      optInSignalPeriod = 9;
   else if( (int)optInSignalPeriod < 1 || (int)optInSignalPeriod > 100000 )
      return -1;
   legMax = optInROC1Period + optInSMA1Period - 1;
   leg = optInROC2Period + optInSMA2Period - 1;
   if( leg > legMax )
   {
      legMax = leg;
   }
   leg = optInROC3Period + optInSMA3Period - 1;
   if( leg > legMax )
   {
      legMax = leg;
   }
   leg = optInROC4Period + optInSMA4Period - 1;
   if( leg > legMax )
   {
      legMax = leg;
   }
   return legMax + optInSignalPeriod - 1;
}
int ti_obv_start(double const *options) {
    (void)options;
    return 0;
}
int ti_obv(int size, double const *const *inputs, double const *options, double *const *outputs) {
    const double *close = inputs[0];
    const double *volume = inputs[1];
    (void)options;
    double *output = outputs[0];
    double sum = 0;
    *output++ = sum;
    double prev = close[0];
    int i;
    for (i = 1; i < size; ++i) {
        if (close[i] > prev) {
            sum += volume[i];
        } else if (close[i] < prev) {
            sum -= volume[i];
        } else {
        }
        prev = close[i];
        *output++ = sum;
    }
    return 0;
}
