TA_RetCode TA_VAR( int startIdx,
                              int endIdx,
                              const double inReal[],
                              int optInTimePeriod,
                              double optInNbDev,
                              int *outBegIdx,
                              int *outNBElement,
                              double outReal[] )
{
   double tempReal;
   double shift;
   double periodTotal1;
   double periodTotal2;
   double meanValue1;
   double variance;
   double invPeriod;
   double peakTotal2;
   int i;
   int j;
   int outIdx;
   int trailingIdx;
   int windowStart;
   int nbInitialElementNeeded;
   int barsSinceReseed;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 5;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( optInNbDev == (-4e+37) )
      optInNbDev = 1;
   else if( !(optInNbDev >= (-3e+37) && optInNbDev <= (3e+37)) )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   nbInitialElementNeeded = optInTimePeriod - 1;
   if( startIdx < nbInitialElementNeeded )
   {
      startIdx = nbInitialElementNeeded;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   invPeriod = 1.0 / (double)optInTimePeriod;
   trailingIdx = startIdx - nbInitialElementNeeded;
   shift = inReal[trailingIdx];
   periodTotal1 = 0.0;
   periodTotal2 = 0.0;
   for( j = trailingIdx; j < startIdx; j += 1 )
   {
      tempReal = inReal[j] - shift;
      periodTotal1 += tempReal;
      tempReal *= tempReal;
      periodTotal2 += tempReal;
   }
   i = startIdx;
   outIdx = 0;
   barsSinceReseed = 32 * optInTimePeriod;
   peakTotal2 = periodTotal2;
   do
   {
      tempReal = inReal[i] - shift;
      periodTotal1 += tempReal;
      tempReal *= tempReal;
      periodTotal2 += tempReal;
      peakTotal2 = (periodTotal2 > peakTotal2) ? periodTotal2 : peakTotal2;
      meanValue1 = periodTotal1 * invPeriod;
      variance = periodTotal2 * invPeriod - meanValue1 * meanValue1;
      tempReal = inReal[trailingIdx] - shift;
      periodTotal1 -= tempReal;
      tempReal *= tempReal;
      periodTotal2 -= tempReal;
      trailingIdx += 1;
      barsSinceReseed -= 1;
      if( variance < 0.000001 * (peakTotal2 * invPeriod) || barsSinceReseed <= 0 )
      {
         barsSinceReseed = 32 * optInTimePeriod;
         windowStart = i - nbInitialElementNeeded;
         tempReal = 0.0;
         for( j = windowStart; j <= i; j += 1 )
         {
            tempReal += inReal[j];
         }
         shift = tempReal * invPeriod;
         periodTotal1 = 0.0;
         periodTotal2 = 0.0;
         for( j = windowStart; j <= i; j += 1 )
         {
            tempReal = inReal[j] - shift;
            periodTotal1 += tempReal;
            tempReal *= tempReal;
            periodTotal2 += tempReal;
         }
         meanValue1 = periodTotal1 * invPeriod;
         variance = periodTotal2 * invPeriod - meanValue1 * meanValue1;
         if( variance < 0.000001 * (periodTotal2 * invPeriod) )
         {
            shift = inReal[i];
            periodTotal1 = 0.0;
            periodTotal2 = 0.0;
            for( j = windowStart; j <= i; j += 1 )
            {
               tempReal = inReal[j] - shift;
               periodTotal1 += tempReal;
               tempReal *= tempReal;
               periodTotal2 += tempReal;
            }
            meanValue1 = periodTotal1 * invPeriod;
            variance = periodTotal2 * invPeriod - meanValue1 * meanValue1;
         }
         peakTotal2 = periodTotal2;
         if( variance < 0.000000000001 * (periodTotal2 * invPeriod) )
         {
            variance = 0.0;
         }
         tempReal = inReal[windowStart] - shift;
         periodTotal1 -= tempReal;
         tempReal *= tempReal;
         periodTotal2 -= tempReal;
      }
      outReal[outIdx++] = variance;
      i += 1;
   } while( i <= endIdx );
   *outNBElement= outIdx;
   *outBegIdx= startIdx;
   return TA_SUCCESS;
}
