   {
      return retCode;
   }
   if( optInNbDev != 1.0 )
   {
      for( i = 0; i < (int)*outNBElement; i += 1 )
      {
         outReal[i] = sqrt(outReal[i]) * optInNbDev;
      }
   } else
   {
      for( i = 0; i < (int)*outNBElement; i += 1 )
      {
         outReal[i] = sqrt(outReal[i]);
      }
   }
