   int lookbackTotal;
   int outIdx;
   int i;
   double local_rawBuffer[50];
   double *rawBuffer = &local_rawBuffer[0];
   int rawBuffer_Idx;
   int maxIdx_rawBuffer;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 14;
   else if( (int)optInTimePeriod < 1 || (int)optInTimePeriod > 100000 )
      return TA_BAD_PARAM;
   if( optInVolumeDivisor == (-4e+37) )
      optInVolumeDivisor = 10000;
   else if( !(optInVolumeDivisor >= 1e0 && optInVolumeDivisor <= (3e+37)) )
      return TA_BAD_PARAM;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inVolume )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   lookbackTotal = TA_EMV_Lookback(optInTimePeriod,optInVolumeDivisor);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      *outBegIdx= 0;
      *outNBElement= 0;
      return TA_SUCCESS;
   }
   if( optInTimePeriod < 1 ) return ((TA_RetCode)(TA_INTERNAL_ERROR+440));
