TA_RetCode TA_AD( int startIdx,
                             int endIdx,
                             const double inHigh[],
                             const double inLow[],
                             const double inClose[],
                             const double inVolume[],
                             int *outBegIdx,
                             int *outNBElement,
                             double outReal[] )
{
   int nbBar;
   int currentBar;
   int outIdx;
   double high;
   double low;
   double close;
   double tmp;
   double ad;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( !inHigh )
      return TA_BAD_PARAM;
   if( !inLow )
      return TA_BAD_PARAM;
   if( !inClose )
      return TA_BAD_PARAM;
   if( !inVolume )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   nbBar = endIdx - startIdx + 1;
   *outNBElement= nbBar;
   *outBegIdx= startIdx;
   currentBar = startIdx;
   outIdx = 0;
   ad = 0.0;
   while( nbBar != 0 )
   {
      high = inHigh[currentBar];
      low = inLow[currentBar];
      tmp = high - low;
      close = inClose[currentBar];
      if( tmp > 0.0 )
      {
         ad += (close - low - (high - close)) / tmp * (double)inVolume[currentBar];
      }
      outReal[outIdx++] = ad;
      currentBar += 1;
      nbBar -= 1;
   }
   return TA_SUCCESS;
}
int TA_AD_Lookback( void )
{
   return 0;
}
