      return TA_BAD_PARAM;
   if( !inReal1 )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   S_xx = 0.0;
   S_xy = 0.0;
   S_x = 0.0;
   S_y = 0.0;
   last_price_x = 0.0;
   last_price_y = 0.0;
   trailing_last_price_x = 0.0;
   trailing_last_price_y = 0.0;
   tmp_real = 0.0;
   shift_x = 0.0;
   shift_y = 0.0;
   denom = 0.0;
   denom_scale = 0.0;
   prev_x = 0.0;
   leaving_xx = 0.0;
   leaving_yy = 0.0;
   S_yy = 0.0;
   prev_y = 0.0;
   n = 0.0;
