   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 20;
   else if( (int)optInTimePeriod < 5 || (int)optInTimePeriod > 2000 )
      return TA_BAD_PARAM;
   if( optInDelta == (-4e+37) )
      optInDelta = 0.1;
   else if( !(optInDelta >= 5e-2 && optInDelta <= 5e-1) )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   *outBegIdx= 0;
   *outNBElement= 0;
   lookbackTotal = TA_SWAK_BP_Lookback(optInTimePeriod,optInDelta);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      return TA_SUCCESS;
   }
   w = 2.0 * 3.141592653589793 / (double)optInTimePeriod;
   beta = cos(w);
   t = 4.0 * 3.141592653589793 * optInDelta / (double)optInTimePeriod;
