      return -1;
   if( optInAccelerationMaxShort == (-4e+37) )
      optInAccelerationMaxShort = 0.2;
   else if( !(optInAccelerationMaxShort >= 0e0 && optInAccelerationMaxShort <= (3e+37)) )
      return -1;
