TA_RetCode TA_PERCENTRANK( int startIdx,
                                      int endIdx,
                                      const double inReal[],
                                      int optInTimePeriod,
                                      int *outBegIdx,
                                      int *outNBElement,
                                      double outReal[] )
{
   int today;
   int outIdx;
   int lookbackTotal;
   int i;
   int count;
   double current;
   if( (startIdx < 0) || (startIdx > 100000000) )
      return TA_OUT_OF_RANGE_START_INDEX;
   if( (endIdx < 0) || (endIdx > 100000000) || (endIdx < startIdx) )
      return TA_OUT_OF_RANGE_END_INDEX;
   if( (int)optInTimePeriod == ((-0x7fffffff - 1)) )
      optInTimePeriod = 100;
   else if( (int)optInTimePeriod < 2 || (int)optInTimePeriod > 10000 )
      return TA_BAD_PARAM;
   if( !inReal )
      return TA_BAD_PARAM;
   if( !outBegIdx || !outNBElement )
      return TA_BAD_PARAM;
   if( !outReal )
      return TA_BAD_PARAM;
   *outBegIdx= 0;
   *outNBElement= 0;
   lookbackTotal = TA_PERCENTRANK_Lookback(optInTimePeriod);
   if( startIdx < lookbackTotal )
   {
      startIdx = lookbackTotal;
   }
   if( startIdx > endIdx )
   {
      return TA_SUCCESS;
   }
   outIdx = 0;
   today = startIdx;
   while( today <= endIdx )
   {
      current = inReal[today];
      count = 0;
      for( i = optInTimePeriod; i >= 1; i -= 1 )
      {
         if( inReal[today - i] < current )
         {
            count += 1;
         }
      }
      outReal[outIdx] = (double)count / (double)optInTimePeriod * 100.0;
      outIdx += 1;
      today += 1;
   }
   *outBegIdx= startIdx;
   *outNBElement= outIdx;
   return TA_SUCCESS;
}
